            let diff = *diff;
            let predicate1 = (resp_o is Some &&
                                resp_o.unwrap() is KResponse &&
                                resp_o.unwrap().arrow_KResponse_0() is CreateResponse);
            let predicate2 = resp_o.unwrap().arrow_KResponse_0().arrow_CreateResponse_0().res;

            if !(predicate1 && predicate2 is Ok) {
                (error_state(state), None)
            } else if diff == 0 {
                let state_prime = VReplicaSetReconcileState {
                    reconcile_step: VReplicaSetRecStepView::Done,
                    ..state
                };
